// Per-route SEO data: titles, descriptions, share images and JSON-LD.
// Rendered into <head> by components/Seo.tsx.
import { COLOURS, SPECS } from './pages/redesign/data';

export const SITE_URL = 'https://www.dondaxlimited.com';

export const absoluteUrl = (path: string) => SITE_URL + path;

/** 1200×630 JPEG share cards, generated by scripts/generate-seo-assets.mjs */
const OG_BRAND = { src: '/og/dondax.jpg', alt: 'DondaX logo' };
const OG_GN_MODEL = { src: '/og/gn-model.jpg', alt: 'DondaX GN Model electric motorcycle in Midnight Black' };

const ORGANIZATION = {
  '@context': 'https://schema.org',
  '@type': 'Organization',
  '@id': `${SITE_URL}/#organization`,
  name: 'DondaX Limited',
  alternateName: 'DondaX',
  url: `${SITE_URL}/`,
  logo: absoluteUrl('/icon-512.png'),
  email: 'care@dondaxlimited.com',
  address: {
    '@type': 'PostalAddress',
    addressLocality: 'Gwarinpa, Abuja',
    addressCountry: 'NG',
  },
  sameAs: ['https://www.instagram.com/dondaxltd', 'https://www.tiktok.com/@dondaxltd'],
};

const WEBSITE = {
  '@context': 'https://schema.org',
  '@type': 'WebSite',
  name: 'DondaX',
  url: `${SITE_URL}/`,
  publisher: { '@id': `${SITE_URL}/#organization` },
};

// Specs come straight from data.ts. There's no list price on the site
// ("On request"), so the Product has no `offers`.
const GN_MODEL_PRODUCT = {
  '@context': 'https://schema.org',
  '@type': 'Product',
  '@id': `${SITE_URL}/products/gn-model#product`,
  name: 'DondaX GN Model',
  description:
    'Built for the city. Smart connectivity, advanced lithium-ion battery technology, and a design that turns heads — the everyday electric motorcycle for African cities.',
  category: 'Electric motorcycle',
  url: absoluteUrl('/products/gn-model'),
  image: COLOURS.map((c) => absoluteUrl(c.image)),
  brand: { '@type': 'Brand', name: 'DondaX' },
  manufacturer: { '@type': 'Organization', name: 'DondaX Limited', url: `${SITE_URL}/` },
  additionalProperty: SPECS.map((s) => ({ '@type': 'PropertyValue', name: s.label, value: s.value })),
};

function breadcrumbs(trail: [name: string, path: string][]) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [['Home', '/'] as const, ...trail].map(([name, path], i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name,
      item: absoluteUrl(path),
    })),
  };
}

export interface PageSeo {
  /** route path; also the canonical / og:url. Omit for pages that shouldn't be indexed. */
  path?: string;
  title: string;
  description: string;
  image: { src: string; alt: string };
  noindex?: boolean;
  jsonLd?: object[];
}

export const PAGES = {
  home: {
    path: '/',
    title: "DondaX — Nigeria's Premier Electric Motorcycle Company",
    description:
      'DondaX is a Nigerian electric motorcycle company. Meet the GN Model: 100 km range, 120 km/h top speed and 2–3 hour charging, built for African cities.',
    image: OG_BRAND,
    jsonLd: [ORGANIZATION, WEBSITE],
  },
  products: {
    path: '/products',
    title: 'DondaX Motors — Our Electric Motorcycle Lineup',
    description:
      'Explore the DondaX electric motorcycle lineup: the GN Model in Midnight Black, Electric Green and Signal Red, with 100 km range and 120 km/h top speed.',
    image: OG_GN_MODEL,
    jsonLd: [breadcrumbs([['Products', '/products']])],
  },
  gnModel: {
    path: '/products/gn-model',
    title: 'DondaX GN Model — Electric Motorcycle',
    description:
      'DondaX GN Model electric motorcycle: 100 km range, 120 km/h top speed, 2–3 hr charge time and 95 kg weight. Three colours. Order yours in Nigeria.',
    image: OG_GN_MODEL,
    jsonLd: [
      GN_MODEL_PRODUCT,
      breadcrumbs([
        ['Products', '/products'],
        ['GN Model', '/products/gn-model'],
      ]),
    ],
  },
  order: {
    path: '/order',
    title: 'Place an Order Request — DondaX GN Model',
    description:
      'Request a DondaX GN Model electric motorcycle in Midnight Black, Electric Green or Signal Red. Our team will contact you with pricing and delivery details.',
    image: OG_GN_MODEL,
    jsonLd: [breadcrumbs([['Order', '/order']])],
  },
  gnhub: {
    path: '/gnhub',
    title: 'GNHub — DondaX Stories, Media & Updates',
    description:
      'News, launches and events from DondaX, the Nigerian electric motorcycle company: GN Model updates, test rides in Abuja and company milestones.',
    image: OG_BRAND,
    jsonLd: [breadcrumbs([['GNHub', '/gnhub']])],
  },
  notFound: {
    title: 'Page Not Found — DondaX',
    description: "The page you're looking for doesn't exist. Explore DondaX electric motorcycles instead.",
    image: OG_BRAND,
    noindex: true,
  },
} satisfies Record<string, PageSeo>;

/** Indexable routes, in sitemap order. The prerender script renders each one. */
export const ROUTES = Object.values(PAGES).flatMap((p) => ('path' in p ? [p.path] : []));
